-- ---------------------------------------------------------------------
-- 0001_admin_profiles_usage.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Admin / Profiles / Usage  (migration 0001)
-- ────────────────────────────────────────────────────────────────────────────
-- Run this in the Supabase SQL editor (Dashboard → SQL → New query → Run).
-- It is IDEMPOTENT and NON-DESTRUCTIVE: it only adds what is missing, so it is
-- safe to run against the existing `profiles` table (which already holds
-- id / email / full_name / avatar_url / subscription_tier from the OAuth
-- callback) and safe to re-run.
--
-- After running:
--   • Confirm `vwanheda@gmail.com` shows role='admin' in `profiles`.
--   • The public `logos` bucket + its policies are created by section 9 below.
-- ════════════════════════════════════════════════════════════════════════════

-- ── 1. profiles ─────────────────────────────────────────────────────────────
-- Create only if it doesn't exist yet; otherwise we just add the new columns.
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade
);

-- New columns (each guarded, so existing rows/data are untouched).
alter table public.profiles add column if not exists email          text;
alter table public.profiles add column if not exists role           text not null default 'member';   -- 'member' | 'admin' | 'owner'
alter table public.profiles add column if not exists tier           text not null default 'free';     -- 'free' | 'pro' | 'growth'
alter table public.profiles add column if not exists business_name  text;
alter table public.profiles add column if not exists business_type  text;                              -- restaurant/retail/service/mine/hospitality/other
alter table public.profiles add column if not exists industry       text;
alter table public.profiles add column if not exists location       text default 'Lusaka';
alter table public.profiles add column if not exists currency       text default 'ZMW';
alter table public.profiles add column if not exists phone          text;
alter table public.profiles add column if not exists whatsapp       text;
alter table public.profiles add column if not exists contact_email  text;
alter table public.profiles add column if not exists logo_url       text;
alter table public.profiles add column if not exists tier_source    text default 'self';               -- 'self' | 'payment' | 'admin_demo'
alter table public.profiles add column if not exists tier_granted_by text;
alter table public.profiles add column if not exists tier_granted_at timestamptz;
alter table public.profiles add column if not exists created_at     timestamptz default now();
alter table public.profiles add column if not exists updated_at     timestamptz default now();
alter table public.profiles add column if not exists last_active_at timestamptz;

-- Legacy columns the OAuth callback writes — keep them present so nothing breaks.
alter table public.profiles add column if not exists full_name         text;
alter table public.profiles add column if not exists avatar_url        text;
alter table public.profiles add column if not exists subscription_tier text default 'free';

-- Backfill the authoritative `tier` from the legacy `subscription_tier` where a
-- row predates this migration. coalesce keeps any real value already set.
update public.profiles
   set tier = coalesce(nullif(tier, ''), nullif(subscription_tier, ''), 'free')
 where tier is null or tier = '';

-- Keep business_name seeded from full_name for pre-existing rows (display only).
update public.profiles
   set business_name = full_name
 where business_name is null and full_name is not null;

-- ── 2. usage_events ─────────────────────────────────────────────────────────
create table if not exists public.usage_events (
  id         bigserial primary key,
  user_id    uuid references auth.users(id) on delete cascade,
  event      text not null,                 -- 'login'|'upload'|'chat'|'engine_view'|'page_view'
  engine     text,                          -- 'engine1'|'engine2'|'engine3'|'cross' (nullable)
  meta       jsonb default '{}'::jsonb,
  created_at timestamptz default now()
);
create index if not exists usage_events_user_idx    on public.usage_events(user_id);
create index if not exists usage_events_event_idx   on public.usage_events(event);
create index if not exists usage_events_created_idx on public.usage_events(created_at desc);

-- ── 3. admin_audit ──────────────────────────────────────────────────────────
create table if not exists public.admin_audit (
  id             bigserial primary key,
  admin_email    text not null,
  target_user_id uuid,
  action         text not null,             -- e.g. 'set_tier'
  detail         jsonb default '{}'::jsonb,
  created_at     timestamptz default now()
);
create index if not exists admin_audit_target_idx  on public.admin_audit(target_user_id);
create index if not exists admin_audit_created_idx on public.admin_audit(created_at desc);

-- ── 4. is_admin() helper ────────────────────────────────────────────────────
-- True when the *current* auth user has role='admin'. Used by RLS policies.
-- SECURITY DEFINER so the policy check itself isn't blocked by RLS on profiles.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
     where id = auth.uid() and role = 'admin'
  );
$$;

-- ── 5. updated_at trigger ───────────────────────────────────────────────────
create or replace function public.set_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists profiles_set_updated_at on public.profiles;
create trigger profiles_set_updated_at
  before update on public.profiles
  for each row execute function public.set_updated_at();

-- ── 5b. Privilege guard ─────────────────────────────────────────────────────
-- RLS lets a user update their own row, which would otherwise let them self-set
-- role='admin'. This trigger pins `role` to its old value for ordinary
-- authenticated self-updates. The service-role client (auth.uid() is null, used
-- by the admin API) and existing admins are unaffected, so legitimate promotions
-- still work. `tier` is intentionally NOT pinned — the checkout flow updates the
-- user's own tier, and tier-gating is a client UX gate (see SECURITY.md).
create or replace function public.guard_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is not null and not public.is_admin() then
    new.role := old.role;
  end if;
  return new;
end;
$$;

drop trigger if exists profiles_guard_role on public.profiles;
create trigger profiles_guard_role
  before update on public.profiles
  for each row execute function public.guard_profile_role();

-- ── 6. Row Level Security ───────────────────────────────────────────────────
alter table public.profiles     enable row level security;
alter table public.usage_events enable row level security;
alter table public.admin_audit  enable row level security;

-- profiles: self read/update; admins read/update all; self insert (provisioning).
drop policy if exists profiles_select_self      on public.profiles;
drop policy if exists profiles_select_admin     on public.profiles;
drop policy if exists profiles_update_self      on public.profiles;
drop policy if exists profiles_update_admin     on public.profiles;
drop policy if exists profiles_insert_self      on public.profiles;

create policy profiles_select_self  on public.profiles for select using (auth.uid() = id);
create policy profiles_select_admin on public.profiles for select using (public.is_admin());
create policy profiles_update_self  on public.profiles for update using (auth.uid() = id) with check (auth.uid() = id);
create policy profiles_update_admin on public.profiles for update using (public.is_admin()) with check (public.is_admin());
create policy profiles_insert_self  on public.profiles for insert with check (auth.uid() = id);

-- usage_events: insert own, read own; admins read all.
drop policy if exists usage_insert_self  on public.usage_events;
drop policy if exists usage_select_self  on public.usage_events;
drop policy if exists usage_select_admin on public.usage_events;

create policy usage_insert_self  on public.usage_events for insert with check (auth.uid() = user_id);
create policy usage_select_self  on public.usage_events for select using (auth.uid() = user_id);
create policy usage_select_admin on public.usage_events for select using (public.is_admin());

-- admin_audit: admins read; writes go through the service-role server route only
-- (service role bypasses RLS, so no insert policy is granted to normal users).
drop policy if exists audit_select_admin on public.admin_audit;
create policy audit_select_admin on public.admin_audit for select using (public.is_admin());

-- ── 7. admin_account_overview view ──────────────────────────────────────────
-- One cheap select for the admin Accounts table: each profile + its usage counts.
-- security_invoker so the caller's RLS applies (admins see all; service role sees
-- all). Created on Postgres 15+ (Supabase default).
create or replace view public.admin_account_overview
with (security_invoker = true) as
select
  p.id,
  p.email,
  p.business_name,
  p.business_type,
  p.role,
  p.tier,
  p.tier_source,
  p.tier_granted_by,
  p.tier_granted_at,
  p.logo_url,
  p.created_at,
  p.last_active_at,
  coalesce(u.uploads, 0)  as uploads,
  coalesce(u.chats, 0)    as chats,
  coalesce(u.events, 0)   as events,
  u.last_event_at
from public.profiles p
left join (
  select
    user_id,
    count(*) filter (where event = 'upload') as uploads,
    count(*) filter (where event = 'chat')   as chats,
    count(*)                                  as events,
    max(created_at)                           as last_event_at
  from public.usage_events
  group by user_id
) u on u.user_id = p.id;

-- ── 8. Seed the bootstrap admin ─────────────────────────────────────────────
-- If the owner's profile row already exists, promote it. (If it doesn't exist
-- yet, the OAuth callback seeds role='admin' for allowlisted emails on next
-- login — see app/auth/callback/route.ts.)
update public.profiles set role = 'admin' where email = 'vwanheda@gmail.com';

-- ── 9. Profile-logo storage bucket ──────────────────────────────────────────
-- Public bucket so getPublicUrl() renders the logo without auth. Writes are
-- still gated by the two policies below: an authenticated user may only create
-- or replace files inside their own `<user-id>/...` folder. No SELECT/DELETE
-- policy is needed — public buckets serve reads, and the app never deletes.
insert into storage.buckets (id, name, public)
values ('logos', 'logos', true)
on conflict (id) do nothing;

drop policy if exists "logos upload own folder" on storage.objects;
create policy "logos upload own folder"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'logos' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists "logos update own folder" on storage.objects;
create policy "logos update own folder"
  on storage.objects for update to authenticated
  using      (bucket_id = 'logos' and (storage.foldername(name))[1] = auth.uid()::text)
  with check (bucket_id = 'logos' and (storage.foldername(name))[1] = auth.uid()::text);

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0001
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0002_fix_profiles_rls.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Migration 0002: fix `profiles` self-access under RLS
--
-- Symptom this fixes: a signed-in user reading their OWN profiles row from the
-- browser got `null` back (role/tier/business_name all empty), even though the
-- row clearly exists. The app currently works around it by reading/writing the
-- profile through the service-role route `/api/profile`. This migration repairs
-- the database itself so direct, RLS-scoped self-access works again.
--
-- Root cause covered: (1) the `authenticated`/`anon` roles may lack the base
-- table GRANTs (RLS can only narrow what a role is already granted — with no
-- GRANT, every read is denied and surfaces as null), and (2) the self-access
-- policies are re-asserted cleanly. `is_admin()` stays SECURITY DEFINER so the
-- admin policy never recurses into RLS on `profiles`.
--
-- Idempotent and safe to re-run. Run in the Supabase SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

-- 1. Base privileges. Without these, RLS policies are moot (no grant = no rows).
grant usage on schema public to anon, authenticated;
grant select, insert, update on public.profiles      to authenticated;
grant select, insert            on public.usage_events to authenticated;
grant select on public.admin_account_overview to authenticated;

-- 2. Make sure RLS is on (the policies below are the actual access rules).
alter table public.profiles enable row level security;

-- 3. Re-assert the self-access policies (drop-then-create = idempotent).
drop policy if exists profiles_select_self  on public.profiles;
drop policy if exists profiles_update_self  on public.profiles;
drop policy if exists profiles_insert_self  on public.profiles;

create policy profiles_select_self
  on public.profiles for select
  to authenticated
  using (auth.uid() = id);

create policy profiles_update_self
  on public.profiles for update
  to authenticated
  using (auth.uid() = id)
  with check (auth.uid() = id);

create policy profiles_insert_self
  on public.profiles for insert
  to authenticated
  with check (auth.uid() = id);

-- 4. Admin can read/update every row (is_admin() is SECURITY DEFINER → no
--    recursion into profiles RLS).
drop policy if exists profiles_select_admin on public.profiles;
drop policy if exists profiles_update_admin on public.profiles;

create policy profiles_select_admin
  on public.profiles for select
  to authenticated
  using (public.is_admin());

create policy profiles_update_admin
  on public.profiles for update
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0002
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0003_function_proposals.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Migration 0003: function_proposals (SAFEGUARD.md — Layer 2)
--
-- The owner-only review queue for AI/rule-proposed derived-metric functions.
-- Proposals are DATA (a validated formula + sandbox preview + critique verdict);
-- nothing here executes. Only admins can read/write. Run in the SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

create table if not exists public.function_proposals (
  id            uuid primary key default gen_random_uuid(),
  name          text not null,
  purpose       text,
  extends_engine text,
  inputs        jsonb not null default '[]',
  formula       text not null,
  preview       jsonb not null default '{}',
  confidence    numeric not null default 0,
  citations     jsonb not null default '[]',
  assumptions   jsonb not null default '[]',
  risks         jsonb not null default '[]',
  critique      jsonb not null default '{}',
  source        text not null default 'rule',   -- 'rule' | 'ai'
  status        text not null default 'proposed', -- proposed|approved|rejected|implemented
  source_file   text,
  created_by    text,
  created_at    timestamptz not null default now(),
  reviewed_by   text,
  reviewed_at   timestamptz
);

create index if not exists function_proposals_status_idx  on public.function_proposals(status);
create index if not exists function_proposals_created_idx on public.function_proposals(created_at desc);

alter table public.function_proposals enable row level security;

-- Admin-only (is_admin() is SECURITY DEFINER — no recursion). Writes also happen
-- via the service-role admin route, which bypasses RLS.
drop policy if exists function_proposals_admin_all on public.function_proposals;
create policy function_proposals_admin_all
  on public.function_proposals for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

grant select, insert, update on public.function_proposals to authenticated;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0003
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0004_proposal_monitoring.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Migration 0004: Monitoring & Evaluation for function proposals
-- (SAFEGUARD.md — Layer 3). Raises the guard: approval no longer makes a metric
-- final. An approved metric enters a 15-day MONITORING window during which it is
-- re-critiqued on every use; only after the window passes with zero failures can
-- it be promoted to 'stable'. Run in the Supabase SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

alter table public.function_proposals
  add column if not exists monitor_until     timestamptz,
  add column if not exists monitor_runs      int not null default 0,
  add column if not exists monitor_fails     int not null default 0,
  add column if not exists last_monitored_at timestamptz;

-- status vocabulary is now:
--   proposed | rejected | monitoring | stable | implemented
-- (free text — no enum change needed; documented here for clarity)

create index if not exists function_proposals_monitor_idx
  on public.function_proposals(status, monitor_until);

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0004
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0005_business_events.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Business Events  (migration 0005)   ·   Evolution spine
-- ────────────────────────────────────────────────────────────────────────────
-- Implements RFC-001 (docs/evolution/01_BUSINESS_EVENT_SCHEMA.md): the canonical,
-- append-only log of Business Events — the atomic unit of AIBOS (Bible Ch.5).
--
-- IDEMPOTENT & NON-DESTRUCTIVE: create-if-not-exists + add-column-if-not-exists,
-- safe to re-run. Tenant key is `user_id` (ADR-001 D2), mirroring usage_events;
-- a reserved nullable `business_id` is the future multi-branch seam (unused now).
-- Reuses the existing public.set_updated_at() and is_admin() from migration 0001.
-- Run in the Supabase SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

-- ── 1. business_events ───────────────────────────────────────────────────────
create table if not exists public.business_events (
  id             uuid primary key default gen_random_uuid(),
  schema_version integer     not null default 1,
  user_id        uuid        not null references auth.users(id) on delete cascade,
  business_id    uuid,                                  -- reserved seam (ADR-001 D2), null in v1

  event_type     text        not null,                 -- see check below (RFC-001 §2)
  occurred_at    timestamptz not null default now(),   -- when it happened in the business
  recorded_at    timestamptz not null default now(),   -- when AIBOS captured it

  source         text        not null default 'manual',-- manual|voice|receipt|qr|excel|csv|pos|api
  confidence     numeric     not null default 1.0,      -- 0..1
  status         text        not null default 'pending',-- pending|confirmed|void

  payload        jsonb       not null default '{}'::jsonb,
  corrections    jsonb       not null default '{}'::jsonb,  -- user edits → Business Memory (Init 13)
  audit          jsonb       not null default '[]'::jsonb,  -- append-only history (Init 5)

  created_by     uuid,                                  -- acting user (= user_id in v1)
  reversed_by    uuid,                                  -- the event that voids this one, if any

  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

-- Guarded constraints (added only if missing, so re-runs don't error).
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'business_events_type_chk') then
    alter table public.business_events add constraint business_events_type_chk
      check (event_type in (
        'Sale','Purchase','Expense','InventoryReceipt','InventoryAdjustment',
        'Salary','SupplierPayment','CustomerPayment','AssetPurchase',
        'TaxPayment','Loan','Refund','Transfer'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'business_events_status_chk') then
    alter table public.business_events add constraint business_events_status_chk
      check (status in ('pending','confirmed','void'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'business_events_source_chk') then
    alter table public.business_events add constraint business_events_source_chk
      check (source in ('manual','voice','receipt','qr','excel','csv','pos','api'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'business_events_conf_chk') then
    alter table public.business_events add constraint business_events_conf_chk
      check (confidence >= 0 and confidence <= 1);
  end if;
end $$;

-- Indexes: the timeline reads by user newest-first; the twin folds by user+time;
-- status filters confirmed-only into the projection.
create index if not exists business_events_user_idx     on public.business_events(user_id);
create index if not exists business_events_occurred_idx  on public.business_events(user_id, occurred_at desc);
create index if not exists business_events_status_idx    on public.business_events(user_id, status);
create index if not exists business_events_type_idx      on public.business_events(user_id, event_type);

-- updated_at trigger (reuse the function defined in migration 0001).
drop trigger if exists business_events_set_updated_at on public.business_events;
create trigger business_events_set_updated_at
  before update on public.business_events
  for each row execute function public.set_updated_at();

-- ── 2. Row Level Security ────────────────────────────────────────────────────
-- Same proven pattern as usage_events: a user sees & writes only their own rows;
-- admins may read all. The service-role backend bypasses RLS (ADR-001 D4) and is
-- responsible for scoping every query to a JWT-verified user_id.
alter table public.business_events enable row level security;

drop policy if exists business_events_select_self  on public.business_events;
drop policy if exists business_events_select_admin on public.business_events;
drop policy if exists business_events_insert_self  on public.business_events;
drop policy if exists business_events_update_self  on public.business_events;

create policy business_events_select_self  on public.business_events
  for select using (auth.uid() = user_id);
create policy business_events_select_admin on public.business_events
  for select using (public.is_admin());
-- Direct client writes are allowed but self-scoped; the primary write path is the
-- backend pipeline (service role). No DELETE policy — events are soft-voided, never
-- hard-deleted (Initiative 5 audit trail).
create policy business_events_insert_self  on public.business_events
  for insert with check (auth.uid() = user_id);
create policy business_events_update_self  on public.business_events
  for update using (auth.uid() = user_id) with check (auth.uid() = user_id);

grant select, insert, update on public.business_events to authenticated;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0005
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0006_business_state.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Business State / Digital Twin  (migration 0006)   ·   Evolution spine
-- ────────────────────────────────────────────────────────────────────────────
-- The Digital Twin (Directive Initiative 12): a DERIVED, rebuildable projection of
-- the current state of the business — one row per user_id. It is NOT a source of
-- record; business_events is. The twin can be fully reconstructed by replaying the
-- event log (ADR-001 D5), which also gives us free rollback.
--
-- IDEMPOTENT & NON-DESTRUCTIVE. Reuses public.set_updated_at() and is_admin().
-- Run in the Supabase SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

create table if not exists public.business_state (
  user_id        uuid primary key references auth.users(id) on delete cascade,
  currency       text        not null default 'ZMW',

  -- Seed (Phase 3 wizard "initial cash"); cash = opening_cash + net cash flow.
  opening_cash   numeric     not null default 0,
  cash           numeric     not null default 0,

  -- Profit & Loss (confirmed events only).
  total_revenue  numeric     not null default 0,
  total_costs    numeric     not null default 0,
  total_profit   numeric     not null default 0,
  avg_margin     numeric     not null default 0,        -- percentage

  -- Balances.
  receivables    numeric     not null default 0,        -- owed to the business
  payables       numeric     not null default 0,        -- owed by the business
  inventory_value numeric    not null default 0,
  assets_value   numeric     not null default 0,
  liabilities    numeric     not null default 0,

  -- Counts.
  customers      integer     not null default 0,
  suppliers      integer     not null default 0,
  employees      integer     not null default 0,

  -- Health (mirrors engine1: clamp(avg_margin * 2.5, 0, 100)).
  health_score   integer     not null default 0,
  health_label   text        not null default 'No Data',

  -- Monthly P&L bridge for the existing engines / store (RFC-001 §7).
  -- [{month, revenue, costs}] — store.toMonthlyRows() accepts these lowercase keys.
  monthly        jsonb       not null default '[]'::jsonb,

  -- Bookkeeping.
  event_count    integer     not null default 0,        -- confirmed events folded in
  last_event_id  uuid,
  last_event_at  timestamptz,
  rebuilt_at     timestamptz,
  updated_at     timestamptz not null default now()
);

drop trigger if exists business_state_set_updated_at on public.business_state;
create trigger business_state_set_updated_at
  before update on public.business_state
  for each row execute function public.set_updated_at();

-- ── Row Level Security ───────────────────────────────────────────────────────
alter table public.business_state enable row level security;

drop policy if exists business_state_select_self  on public.business_state;
drop policy if exists business_state_select_admin on public.business_state;

-- Read-only to clients (the Timeline/dashboard may read the twin directly via RLS).
-- All WRITES happen through the backend projector (service role) so the twin always
-- equals a fold over the event log — no client may set business state by hand.
create policy business_state_select_self  on public.business_state
  for select using (auth.uid() = user_id);
create policy business_state_select_admin on public.business_state
  for select using (public.is_admin());

grant select on public.business_state to authenticated;

