-- ---------------------------------------------------------------------
-- 0022_business_members.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Team members  (migration 0022)  ·  audit items #27, #28
-- ────────────────────────────────────────────────────────────────────────────
-- One-login tenancy becomes a membership model. A member acts inside the
-- OWNER's tenant (owner_id = the existing user_id tenant key everything is
-- already scoped by), with a role:
--
--   owner       — the account holder; full control (implicit, no row needed)
--   staff       — records events (they land PENDING — the per-role trust gate),
--                 sees Today + Schedule; no money pages, no confirm, no settings
--   accountant  — reads everything + exports; writes nothing
--
-- Backward compatible BY CONSTRUCTION: existing users have no rows, so the
-- resolver (membership.py) treats them as owner of their own tenant — nothing
-- changes until an owner invites someone.
--
-- IDEMPOTENT & NON-DESTRUCTIVE. Run in the Supabase SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

create table if not exists public.business_members (
  id             uuid primary key default gen_random_uuid(),
  owner_id       uuid        not null references auth.users(id) on delete cascade,   -- the tenant
  member_id      uuid        references auth.users(id) on delete cascade,            -- null until invite accepted
  email          text        not null,                                              -- invited address
  role           text        not null default 'staff',
  status         text        not null default 'pending',   -- pending|active|revoked
  invited_by     uuid,
  invited_at     timestamptz not null default now(),
  accepted_at    timestamptz,

  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'business_members_role_chk') then
    alter table public.business_members add constraint business_members_role_chk
      check (role in ('owner','staff','accountant'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'business_members_status_chk') then
    alter table public.business_members add constraint business_members_status_chk
      check (status in ('pending','active','revoked'));
  end if;
  -- One membership per (owner, email); re-inviting updates the same row.
  if not exists (select 1 from pg_constraint where conname = 'business_members_owner_email_uq') then
    alter table public.business_members add constraint business_members_owner_email_uq
      unique (owner_id, email);
  end if;
end $$;

create index if not exists business_members_member_idx on public.business_members(member_id) where member_id is not null;
create index if not exists business_members_owner_idx  on public.business_members(owner_id);
create index if not exists business_members_email_idx  on public.business_members(lower(email));

drop trigger if exists business_members_set_updated_at on public.business_members;
create trigger business_members_set_updated_at
  before update on public.business_members
  for each row execute function public.set_updated_at();

-- ── is_member(): does the caller belong to `tenant` at ≥ the given role rank? ─
-- SECURITY DEFINER so the check itself isn't blocked by RLS. Rank:
-- accountant(1) < staff(1 write) — we treat staff and accountant as siblings,
-- so callers pass the EXACT role set they accept.
create or replace function public.is_member(tenant uuid, roles text[])
returns boolean language sql security definer stable as $$
  select exists (
    select 1 from public.business_members m
    where m.owner_id = tenant
      and m.member_id = auth.uid()
      and m.status = 'active'
      and m.role = any(roles)
  );
$$;

-- ── Row Level Security ────────────────────────────────────────────────────────
-- The owner manages their own roster; a member may read the row that grants
-- them access (to discover which tenant they belong to). Backend writes via
-- service role. No member-side writes.
alter table public.business_members enable row level security;

drop policy if exists business_members_select_owner  on public.business_members;
drop policy if exists business_members_select_self   on public.business_members;
drop policy if exists business_members_write_owner   on public.business_members;
drop policy if exists business_members_select_admin  on public.business_members;

create policy business_members_select_owner on public.business_members
  for select using (auth.uid() = owner_id);
create policy business_members_select_self  on public.business_members
  for select using (auth.uid() = member_id);
create policy business_members_write_owner  on public.business_members
  for all using (auth.uid() = owner_id) with check (auth.uid() = owner_id);
create policy business_members_select_admin on public.business_members
  for select using (public.is_admin());

grant select, insert, update, delete on public.business_members to authenticated;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0022
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0023_businesses.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Multiple businesses under one login  (migration 0023)  ·  audit #16
-- ────────────────────────────────────────────────────────────────────────────
-- The Growth anchor: portfolios (a shop + a salon + two flats), separate books,
-- one login. Backward compatible BY CONSTRUCTION — every existing account is
-- backfilled ONE default business and all its data is stamped with that id, so
-- with a single business every query scopes to it and behaviour is identical.
--
-- ORDER MATTERS on live data (the plan's delicate step): create + backfill the
-- businesses, add business_id columns, backfill them from the default business,
-- THEN re-key business_state to (user_id, business_id). Running top-to-bottom
-- in one editor paste does this correctly. IDEMPOTENT & NON-DESTRUCTIVE.
-- ════════════════════════════════════════════════════════════════════════════

-- ── 1. businesses ────────────────────────────────────────────────────────────
create table if not exists public.businesses (
  id          uuid primary key default gen_random_uuid(),
  owner_id    uuid        not null references auth.users(id) on delete cascade,
  name        text        not null,
  industry    text,
  currency    text        not null default 'ZMW',
  is_default  boolean     not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists businesses_owner_idx on public.businesses(owner_id, created_at);

drop trigger if exists businesses_set_updated_at on public.businesses;
create trigger businesses_set_updated_at
  before update on public.businesses
  for each row execute function public.set_updated_at();

alter table public.businesses enable row level security;
drop policy if exists businesses_select_self on public.businesses;
drop policy if exists businesses_write_self  on public.businesses;
drop policy if exists businesses_select_admin on public.businesses;
create policy businesses_select_self on public.businesses for select using (auth.uid() = owner_id);
create policy businesses_write_self  on public.businesses for all using (auth.uid() = owner_id) with check (auth.uid() = owner_id);
create policy businesses_select_admin on public.businesses for select using (public.is_admin());
grant select, insert, update, delete on public.businesses to authenticated;

-- ── 2. Backfill one default business per existing profile ────────────────────
insert into public.businesses (owner_id, name, industry, currency, is_default)
select p.id,
       coalesce(nullif(trim(p.business_name), ''), 'My business'),
       p.industry,
       coalesce(nullif(p.currency, ''), 'ZMW'),
       true
from public.profiles p
where not exists (select 1 from public.businesses b where b.owner_id = p.id);

-- ── 3. Add business_id to every business-scoped table (nullable) ─────────────
-- business_events already reserved it (0005). Add to the rest.
alter table public.business_state add column if not exists business_id uuid;
alter table public.products       add column if not exists business_id uuid;
alter table public.parties        add column if not exists business_id uuid;
alter table public.invoices       add column if not exists business_id uuid;
alter table public.schedule_items add column if not exists business_id uuid;

-- ── 4. Backfill business_id = the owner's default business ───────────────────
do $$
declare t record;
begin
  for t in
    select unnest(array['business_events','business_state','products','parties','invoices','schedule_items']) as tbl
  loop
    execute format(
      'update public.%I x set business_id = b.id
         from public.businesses b
        where b.owner_id = x.user_id and b.is_default and x.business_id is null', t.tbl);
  end loop;
end $$;

-- ── 5. Re-key business_state to (user_id, business_id) ───────────────────────
-- The delicate step: only run once business_id is backfilled (step 4 above).
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conrelid = 'public.business_state'::regclass and contype = 'p'
      and conname = 'business_state_pkey'
      and (select count(*) from unnest(conkey)) = 1     -- current PK is user_id alone
  ) then
    alter table public.business_state drop constraint business_state_pkey;
    -- default the seam so future single-business inserts never violate NOT NULL
    update public.business_state set business_id = gen_random_uuid() where business_id is null;
    alter table public.business_state alter column business_id set not null;
    alter table public.business_state add constraint business_state_pkey primary key (user_id, business_id);
  end if;
end $$;

create index if not exists business_events_business_idx on public.business_events(user_id, business_id);
create index if not exists products_business_idx        on public.products(user_id, business_id);
create index if not exists parties_business_idx         on public.parties(user_id, business_id);
create index if not exists invoices_business_idx        on public.invoices(user_id, business_id);
create index if not exists schedule_items_business_idx  on public.schedule_items(user_id, business_id);

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0023
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0024_budgets.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Budgets & targets  (migration 0024)  ·  audit item #37
-- ────────────────────────────────────────────────────────────────────────────
-- Variance today only compares month-over-month. A budget lets the owner
-- compare actuals against a PLAN — "I aimed for K50,000 revenue, K30,000
-- costs this month; where am I?" One row per (business, month, metric).
--
-- Actuals are DERIVED from the twin/events on read (never stored); this table
-- holds only the targets the owner set. Business-scoped from birth (audit #16).
-- IDEMPOTENT & NON-DESTRUCTIVE, house conventions. Run in the Supabase editor.
-- ════════════════════════════════════════════════════════════════════════════

create table if not exists public.budgets (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid        not null references auth.users(id) on delete cascade,
  business_id uuid,                                   -- multi-business scope
  month       text        not null,                   -- 'YYYY-MM'
  metric      text        not null,                   -- revenue|costs|profit
  target      numeric     not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'budgets_metric_chk') then
    alter table public.budgets add constraint budgets_metric_chk
      check (metric in ('revenue','costs','profit'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'budgets_uq') then
    alter table public.budgets add constraint budgets_uq
      unique (user_id, business_id, month, metric);
  end if;
end $$;

create index if not exists budgets_user_month_idx on public.budgets(user_id, month);

drop trigger if exists budgets_set_updated_at on public.budgets;
create trigger budgets_set_updated_at
  before update on public.budgets
  for each row execute function public.set_updated_at();

alter table public.budgets enable row level security;
drop policy if exists budgets_select_self on public.budgets;
drop policy if exists budgets_write_self  on public.budgets;
drop policy if exists budgets_select_admin on public.budgets;
create policy budgets_select_self on public.budgets for select using (auth.uid() = user_id);
create policy budgets_write_self  on public.budgets for all using (auth.uid() = user_id) with check (auth.uid() = user_id);
create policy budgets_select_admin on public.budgets for select using (public.is_admin());
grant select, insert, update, delete on public.budgets to authenticated;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0024
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0025_invoice_payments.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AIBOS — Invoice payment links  (migration 0025)   ·   closes the get-paid loop
-- ────────────────────────────────────────────────────────────────────────────
-- 0019 gave the owner an invoice they could SHARE. This lets the customer PAY
-- it: a sent invoice carries an unguessable `pay_token`, the token addresses a
-- public payment page, and a successful mobile-money collection settles the
-- invoice through the SAME invoices.mark_paid() the owner's button uses — so
-- there is exactly one path from "money arrived" to a CustomerPayment event.
--
-- Two things this table exists to prevent:
--
--   1. LOST MONEY ON RESTART. Subscription collections live in an in-memory
--      dict (main.PAYMENTS). That is survivable for a checkout the buyer is
--      watching; it is NOT survivable here, where a customer may approve the
--      prompt minutes later and the provider webhook may arrive after a deploy.
--      A reference the server has forgotten is money taken against an invoice
--      that stays unpaid. So invoice collections are PERSISTED.
--
--   2. DOUBLE SETTLEMENT. `settled` is flipped once, before the spine event is
--      posted, so a re-poll racing the webhook cannot post two CustomerPayments
--      for one collection.
--
-- The token is a capability (same shape as the hospitality iCal feed, 0016):
-- knowing it is the only thing needed to VIEW and PAY the invoice, which is
-- exactly what you want to paste into WhatsApp. It grants nothing else — no
-- account access, no other invoice, no customer list.
--
-- IDEMPOTENT & NON-DESTRUCTIVE, house conventions. Run in the Supabase SQL
-- editor after 0024.
-- ════════════════════════════════════════════════════════════════════════════

-- ── The capability token on the invoice ──────────────────────────────────────
alter table public.invoices add column if not exists pay_token text;

-- Partial unique index: many invoices legitimately have no token yet (drafts,
-- and every invoice issued before this migration), and NULLs must not collide.
create unique index if not exists invoices_pay_token_uq
  on public.invoices(pay_token) where pay_token is not null;

-- ── Collection attempts against an invoice ───────────────────────────────────
create table if not exists public.invoice_payments (
  id            uuid primary key default gen_random_uuid(),
  invoice_id    uuid        not null references public.invoices(id) on delete cascade,
  -- Denormalised so a settlement can find the tenant without re-reading the
  -- invoice, and so RLS below is a single-column check.
  user_id       uuid        not null references auth.users(id) on delete cascade,

  reference     text        not null,        -- provider reference (UUID v4)
  network       text        not null,        -- 'mtn' | 'airtel'
  payer_phone   text,                        -- as entered by the payer
  amount        numeric     not null,        -- server-side from the invoice, never the client
  currency      text        not null default 'ZMW',

  status        text        not null default 'pending',   -- pending|successful|failed
  -- Flipped exactly once, BEFORE the CustomerPayment is posted. The guard that
  -- makes webhook-vs-poll races safe.
  settled       boolean     not null default false,

  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'invoice_payments_status_chk') then
    alter table public.invoice_payments add constraint invoice_payments_status_chk
      check (status in ('pending','successful','failed'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'invoice_payments_network_chk') then
    alter table public.invoice_payments add constraint invoice_payments_network_chk
      check (network in ('mtn','airtel'));
  end if;
  -- The provider reference is how a webhook finds this row. It must be unique
  -- globally, not per-user: the callback arrives with nothing but the reference.
  if not exists (select 1 from pg_constraint where conname = 'invoice_payments_reference_uq') then
    alter table public.invoice_payments add constraint invoice_payments_reference_uq
      unique (reference);
  end if;
end $$;

create index if not exists invoice_payments_invoice_idx on public.invoice_payments(invoice_id);
create index if not exists invoice_payments_user_idx    on public.invoice_payments(user_id, created_at desc);

drop trigger if exists invoice_payments_set_updated_at on public.invoice_payments;
create trigger invoice_payments_set_updated_at
  before update on public.invoice_payments
  for each row execute function public.set_updated_at();

-- ── Row Level Security (house pattern: self + admin-read) ────────────────────
-- The public payment page does NOT read through these policies — it is served
-- by the backend's service-role client after the token is verified, exactly
-- like the hospitality iCal feed. An anonymous visitor never touches Postgres
-- directly, so there is deliberately no anon policy here.
alter table public.invoice_payments enable row level security;

drop policy if exists invoice_payments_select_self  on public.invoice_payments;
drop policy if exists invoice_payments_select_admin on public.invoice_payments;

create policy invoice_payments_select_self  on public.invoice_payments for select using (auth.uid() = user_id);
create policy invoice_payments_select_admin on public.invoice_payments for select using (public.is_admin());

-- Read-only to the client. Rows are written by the backend (service role) as
-- the result of a real provider call — a client that could insert one could
-- claim a payment that never happened.
grant select on public.invoice_payments to authenticated;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0025
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0026_business_identity.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Business identity provenance  (migration 0026)
-- ────────────────────────────────────────────────────────────────────────────
-- The Setup Wizard can now find a business's existing online presence and
-- offer it back as a one-tap pre-fill (aibos-api/identity.py → GET
-- /identity/lookup). The fields it fills ALREADY EXIST on profiles from
-- migration 0001 — business_name, industry, location, phone, logo_url — and
-- from 0007 — operating_hours. This migration adds only what was missing:
--
--   1. `website`            — the listing's site, previously nowhere to put.
--   2. PROVENANCE           — which fields came from outside, from where, and
--                             whether a human confirmed them.
--
-- Provenance is the point. Imported data is a SUGGESTION the owner accepted,
-- not a fact AIBOS observed, and the difference has to survive in the row:
-- nothing derived from an external listing may ever be treated as spine-grade
-- truth. `identity_confirmed_at` is written only when the owner taps "Yes,
-- that's my business" — a NULL there means nothing was ever imported.
--
-- IDEMPOTENT & NON-DESTRUCTIVE. Run in the Supabase SQL editor.
-- ════════════════════════════════════════════════════════════════════════════

alter table public.profiles add column if not exists website               text;
alter table public.profiles add column if not exists identity_place_id     text;         -- Google Places id of the confirmed listing
alter table public.profiles add column if not exists identity_source       text;         -- 'google_places' | null (typed by hand)
alter table public.profiles add column if not exists identity_confirmed_at timestamptz;  -- when the OWNER confirmed the match

-- Finding a business again later (drift checks: "your listing says you now
-- close at 20:00") is a lookup by place id, so index it — sparsely, because
-- most rows will never have one.
create index if not exists profiles_identity_place_id_idx
  on public.profiles (identity_place_id)
  where identity_place_id is not null;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0026
-- ════════════════════════════════════════════════════════════════════════════;


-- ---------------------------------------------------------------------
-- 0027_hospitality_public_site.sql
-- ---------------------------------------------------------------------

-- ════════════════════════════════════════════════════════════════════════════
-- AI-BOS — Hospitality public booking surface  (migration 0027)
-- ────────────────────────────────────────────────────────────────────────────
-- Lets a property's own website read availability and send a booking request
-- without a login. Every /hospitality/* route sits behind require_user, and the
-- only unauthenticated route in the module is the iCal feed. That is correct
-- for staff surfaces and useless for a public website: dunslimapartments.com
-- has no Supabase session and never will.
--
-- Two columns, both mirroring patterns already in this schema:
--
--   • properties.public_site_token — an unguessable token that IS the
--     capability, exactly as channels.ical_export_token already is for the
--     public feed. Null until the owner mints one, so nothing is exposed by
--     upgrading. Rotating it revokes the site instantly.
--
--   • units.public_slug — the handle a website uses in a URL. The website knows
--     its residences as 'mandela', 'mulima' and 'kaunda' and knows nothing about
--     AI-BOS unit ids. Without this the public endpoint would have to match on
--     unit_name, so renaming a unit in the dashboard would quietly break the
--     public site.
--
-- IDEMPOTENT & NON-DESTRUCTIVE. Run in the Supabase SQL editor.
-- RLS already governs both tables from 0015; these only add columns to
-- already-secured tables, so no new policy is needed. The public endpoints read
-- through the service-role client and stay scoped to the token's own property.
-- ════════════════════════════════════════════════════════════════════════════

alter table public.properties
  add column if not exists public_site_token text;

alter table public.units
  add column if not exists public_slug text;

-- The token is the capability, so the lookup must be unique and indexed.
create unique index if not exists properties_site_token_uq
  on public.properties(public_site_token)
  where public_site_token is not null;

-- A slug is only meaningful within one property, and two units in the same
-- property sharing one would make the public route ambiguous.
create unique index if not exists units_property_slug_uq
  on public.units(property_id, public_slug)
  where public_slug is not null;

-- ════════════════════════════════════════════════════════════════════════════
-- End migration 0027
-- ════════════════════════════════════════════════════════════════════════════;

-- ===================== end of rebuild =====================
